-- Basic comparison
SELECT * FROM employees WHERE salary > 50000;

-- Multiple conditions with AND/OR
SELECT * FROM employees
WHERE department = 'IT' AND salary > 60000;

-- IN operator for multiple values
SELECT * FROM employees WHERE department IN ('IT', 'HR', 'Finance');

-- NULL check
SELECT * FROM employees WHERE manager_id IS NULL;

-- Starts with 'J'
SELECT * FROM users WHERE name LIKE 'J%';

-- Contains 'java' anywhere
SELECT * FROM skills WHERE name LIKE '%java%';

-- Ends with '.com'
SELECT * FROM users WHERE email LIKE '%.com';

-- Exactly 4 characters
SELECT * FROM codes WHERE code LIKE '____';

-- Second character is 'a'
SELECT * FROM users WHERE name LIKE '_a%';

-- Numeric range (inclusive)
SELECT * FROM employees WHERE salary BETWEEN 50000 AND 80000;

-- Date range
SELECT * FROM orders
WHERE order_date BETWEEN '2024-01-01' AND '2024-12-31';

-- NOT BETWEEN
SELECT * FROM employees WHERE salary NOT BETWEEN 50000 AND 80000;

-- IN with value list
SELECT * FROM employees WHERE department IN ('IT', 'HR', 'Finance');

-- NOT IN
SELECT * FROM employees WHERE department NOT IN ('HR', 'Legal');

-- IN with subquery
SELECT * FROM employees
WHERE id IN (SELECT manager_id FROM departments);

-- Without parentheses: AND evaluated first
-- Gets IT employees with salary > 60000 OR any HR employee
SELECT * FROM emp WHERE dept = 'HR' OR dept = 'IT' AND salary > 60000;

-- With parentheses: explicit grouping
-- Gets IT or HR employees, all with salary > 60000
SELECT * FROM emp
WHERE (dept = 'HR' OR dept = 'IT') AND salary > 60000;

-- NOT operator
SELECT * FROM emp WHERE NOT dept = 'HR';
